CREATE TEMP TABLE hf AS SELECT hy.*, f.id AS file_id FROM hy JOIN files f ON f.full_code = hy.full_code;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM hf WHERE (SELECT min(start_year)||'-'||max(end_year) FROM file_years y WHERE y.file_id = hf.file_id) IS DISTINCT FROM hf.old) THEN RAISE EXCEPTION 'H: DB years changed since snapshot'; END IF; END $$;
DELETE FROM file_years y USING hf WHERE y.file_id = hf.file_id; INSERT INTO file_years (file_id, start_year, end_year) SELECT hf.file_id, split_part(r, '-', 1)::int, split_part(r, '-', 2)::int FROM hf, unnest(string_to_array(hf.new, ',')) r;

